"""Which kernel command line a boot actually booted, and why nobody could tell.

Why this test exists at all
---------------------------
``stage_esp`` writes ``EFI/UniXNU/unixnu.toml``, and that file's ``args =`` line
is the kernel command line the guest boots.  It can come from two places:

* the caller's ``BootInputs.payload_toml``, copied verbatim -- the payload's own
  delivered line;
* ``vendor/UniXNU-qemu/board.toml``'s ``[payload] kernel_args``, generated by
  :func:`unixnu_boot.kernel_args_line`, when ``payload_toml`` is ``None``.

Nothing in a run's output says which of the two was used, and the two are not the
same line.  Measured on 2026-10-29 against the delivered
``local-private/boot32/boot-inputs`` bundle: the board's line carries
``offline-legacy-surface-wait-ms=600000``, ``sheng-fb-gpu=1`` and
``sheng-gpu-addon=1`` that the payload's ``payload.json kernel_args`` does not,
and the payload's line has none of them.  26 arguments versus 23.

That divergence is not cosmetic, and this is the part that makes it a contract
rather than a curiosity.  ``offline-legacy-surface-wait-ms`` is how long the
display probe waits for ``IOCoreSurfaceRoot``.  The display probe is what calls
``native_legacy_transfer_observed()`` (``package/LegacyDisplayProbe.cpp:242``),
which is the only writer of ``native_legacy_transfer_calls``.  And
``native_hid_input_requested()`` (``package/HidInputProbe.cpp:36-52``) refuses to
consume a Home press while ``native_legacy_transfer_calls < 2``.  So a single
argument that is nominally about the *display* decides whether the *input* path's
consumer ever runs -- and a run that measured one line while believing it
measured the other would report a HID failure caused by an argument it never
knew it had changed.

Fact 131 in ``docs/implementation-plan.md`` is the same failure one layer down:
days lost measuring the wrong inputs.  This test is the cheap half of that
lesson -- it cannot boot anything, and it runs in milliseconds on any host.

What is asserted, and what is deliberately not
----------------------------------------------
Asserted: that the two code paths produce *different* files from *different*
sources, that the delivered one is copied byte-for-byte rather than rewritten,
and that :func:`unipad.host.unixnu_boot.kernel_args_divergence` names a
value change as a change rather than as a removal plus an addition.

Not asserted: which line is *correct*.  That is a build question -- the payload's
``unixnu.toml`` and ``board.toml`` are maintained separately and reconciling them
is not this module's job.  What this module owes a caller is the ability to tell
them apart, and that is what is pinned here.
"""

from __future__ import annotations

import re
import struct
from pathlib import Path
from typing import Any

import pytest

from unipad.host import unixnu_boot as ub
from unipad.host.unixnu_boot import BootInputs

REPO = Path(__file__).resolve().parents[2]

#: The pinned device checkout.  Absent in a clean checkout, which is a skip and
#: not a failure -- the same rule ``test_host_unixnu_boot.py`` follows.
REAL_DEVICE = REPO / "vendor" / "UniXNU-qemu"


# ---------------------------------------------------------------------------
# the minimum a staged ESP needs
# ---------------------------------------------------------------------------
def _adt_node(name: str, properties=(), children=()) -> list:
    """One node of the format ``adt.parse_adt`` reads.

    A transcription of ``make-qemu-adt.py:serialize``, the same shape
    ``test_host_unixnu_boot.py`` and ``test_host_adt.py`` each build for
    themselves.  It is not imported from either of them because it is private to
    those modules, and a test that reaches into another test module's privates
    breaks when that module is refactored -- a worse failure than fifteen lines
    of duplication in a file whose subject is something else entirely.
    """
    return [name, [(key, value) for key, value in properties], list(children)]


def _serialize_adt(node: list) -> bytes:
    _, properties, children = node
    out = struct.pack("<II", len(properties), len(children))
    for key, data in properties:
        out += struct.pack("<32sI", key.encode(), len(data)) + data + bytes(-len(data) % 4)
    return out + b"".join(_serialize_adt(child) for child in children)


def _synthetic_tree() -> bytes:
    """A parseable tree whose ``/chosen/memory-map`` carries a zeroed placeholder.

    The placeholder is what lets ``_check_ramdisk_pair`` accept a config that
    names an initrd: DarwinBoot's gate is an exclusive-or between the file and
    the tree property, and a fixture with only one of the two is refused before
    the ``args`` line is ever written.  Zeroed, because ``AdtNode`` treats a
    nonzero placeholder as compromised data.
    """
    return _serialize_adt(_adt_node("", [("name", b"root\0")], [
        _adt_node("chosen", [("name", b"chosen\0")], [
            _adt_node("memory-map", [("name", b"memory-map\0"), ("TrustCache", bytes(16)),
                                     ("PackedRAMDisk", bytes(16))]),
        ]),
    ]))


def _pe32plus(subsystem: int) -> bytes:
    """A minimal PE32+ image with the subsystem ``pe_subsystem`` reads."""
    blob = bytearray(0x200)
    blob[:2] = b"MZ"
    struct.pack_into("<I", blob, 0x3C, 0x40)          # e_lfanew -> the PE signature
    blob[0x40:0x44] = b"PE\0\0"
    struct.pack_into("<HHIIIHH", blob, 0x44, 0xAA64, 1, 0, 0, 0, 0xF0, 0x22)
    optional = 0x58                                    # straight after the COFF header
    struct.pack_into("<H", blob, optional, 0x20B)      # PE32+ (64-bit)
    struct.pack_into("<H", blob, optional + 68, subsystem)
    return bytes(blob)


def _synthetic_seed(*, logical: int = 1 << 30, extents=((0, 4096),)) -> bytes:
    """A valid ``DBRDISK1`` packed ramdisk, built here rather than shipped.

    ``stage_esp`` validates the seed before it stages it, so a fixture that is
    not one is refused before the ``args`` line is written.  The contract is 32
    header bytes plus one 16-byte extent per dirty region -- see
    ``packed_ramdisk.validate`` for the rules this satisfies.
    """
    blob = struct.pack("<8sIIQQ", b"DBRDISK1", 1, 4096, logical, len(extents))
    payload = b""
    for _, length in extents:
        payload += bytes(length)
    return blob + b"".join(
        struct.pack("<QQ", offset, length) for offset, length in extents
    ) + payload


def _inputs(tmp_path: Path, payload_toml: Path | None) -> BootInputs:
    """Boot inputs whose only interesting field is ``payload_toml``.

    ``unixnu`` is a real PE32+ *application* because ``boot``'s ``pe_subsystem``
    check runs before anything is staged, and a stand-in that is not one would
    fail every test here for the wrong reason.  The device tree is a *parseable*
    tree because ``stage_esp`` reads it back to check the packed-ramdisk pair.
    Everything else is bytes of the right shape: ``stage_esp`` copies files and
    checks names, it executes nothing.
    """
    root = tmp_path / "inputs"
    root.mkdir(parents=True, exist_ok=True)
    firmware = root / "edk2-aarch64-code.fd"
    firmware.write_bytes(b"\0" * 4096)
    kernel = root / "kernel.macho"
    kernel.write_bytes(b"\xcf\xfa\xed\xfe" + b"synthetic kernelcache" * 8)
    devicetree = root / "kernel.macho.adt"
    devicetree.write_bytes(_synthetic_tree())
    darwinboot = root / "DarwinBoot.efi"
    darwinboot.write_bytes(_pe32plus(11) + b"darwinboot-driver" * 3)
    unixnu = root / "UniXNU.efi"
    unixnu.write_bytes(_pe32plus(ub.PE_SUBSYSTEM_APPLICATION) + b"unixnu-application" * 4)
    ramdisk = root / "scratch-data.img"
    ramdisk.write_bytes(_synthetic_seed())
    if payload_toml is not None:
        payload_toml.parent.mkdir(parents=True, exist_ok=True)
        payload_toml.write_text(PAYLOAD_TOML, encoding="utf-8")
    return BootInputs(
        firmware=firmware,
        kernel=kernel,
        devicetree=devicetree,
        darwinboot=darwinboot,
        unixnu=unixnu,
        payload_toml=payload_toml,
        data_ramdisk=ramdisk,
    )


#: A ``unixnu.toml`` in the shape the payload build writes: one driver, one
#: entry, an initrd, and the 23 arguments the delivered bundle carries.  The
#: argument values do not matter; what matters is that they are *not* the board's.
PAYLOAD_TOML = """version = 1
[boot]
timeout = 3
default = "xnu"
[kits]
autoload = false
[[driver]]
path = "Payloads/DarwinBoot.efi"

[[entry]]
id = "xnu"
title = "QEMU virt: source 4K XNU"
type = "xnu"
path = "Payloads/kernel.macho"
initrd = "Payloads/scratch-data.img"
args = "-apfs_shared_datavolume -v serial=3 debug=0x14e offline-hid-input=1 offline-hid-home=1 sheng-touch-hid=1"
"""

#: A board ``[payload]`` block whose line differs from the payload's by exactly
#: one argument, so the divergence under test is a fact about the fixture and not
#: about whatever the pinned vendor tree happens to say today.
BOARD_SPEC: dict[str, Any] = {
    "loader": "driver",
    "title": "QEMU virt: source 4K XNU",
    "kernel_args": ["-v", "serial=3", "offline-hid-input=1", "offline-hid-home=1",
                    "sheng-touch-hid=1", "offline-legacy-surface-wait-ms=600000"],
}

#: The kernel command line the delivered payload at
#: ``local-private/boot32/boot-inputs/payload.json`` carries, transcribed
#: verbatim from the 2026-10-29 measurement (``local-private/tmp/input-e2e/``).
#: Inlined rather than read from that bundle because the bundle is evidence, not
#: repository material: a test that needed it would skip on every clean checkout
#: and pin nothing.
DELIVERED_PAYLOAD_ARGS = (
    "-apfs_shared_datavolume -v serial=3 debug=0x14e kt_fixed_zones=120 "
    "armcpu-diagnostics=1 sheng-pmgr=2 -no_slto_panic "
    "ml-timeout-lock-panic-scale=40 offline-mobile-graphics-load=1 "
    "offline-legacy-register=1 offline-legacy-phase=4 offline-legacy-gop=1 "
    "offline-legacy-unit-scale=1 offline-legacy-pm=1 offline-legacy-validate=1 "
    "offline-legacy-transfer=1 offline-legacy-cpu-present=1 offline-key-events=1 "
    "sheng-aks=1 offline-hid-input=1 offline-hid-home=1 sheng-touch-hid=1"
)


def _staged_args(inputs: BootInputs, tmp_path: Path, spec: dict[str, Any]) -> str:
    """The ``args =`` line ``stage_esp`` writes, read back off the ESP."""
    esp = tmp_path / "esp"
    ub.stage_esp(inputs, esp, spec)
    config = (esp / "EFI/UniXNU/unixnu.toml").read_text(encoding="utf-8")
    match = re.search(r'^\s*args\s*=\s*"(.*)"\s*$', config, re.MULTILINE)
    assert match is not None, config
    return match.group(1)


def test_the_delivered_config_is_staged_byte_for_byte(tmp_path: Path) -> None:
    """``payload_toml`` set means the guest gets that file, unrewritten.

    The whole value of pointing ``payload_toml`` at the payload's own
    ``unixnu.toml`` is that the guest is handed the line the build delivered.  A
    ``stage_esp`` that normalised, reordered or re-spelled it would silently move
    the run back onto the board's line while the caller believed otherwise -- and
    the run would look identical, because both lines boot.
    """
    toml = tmp_path / "delivered" / "unixnu.toml"
    inputs = _inputs(tmp_path, toml)
    esp = tmp_path / "esp"
    ub.stage_esp(inputs, esp, BOARD_SPEC)
    written = (esp / "EFI/UniXNU/unixnu.toml").read_text(encoding="utf-8")
    assert written == PAYLOAD_TOML, written


def test_no_payload_toml_means_the_boards_line_and_it_is_not_the_delivered_one(
    tmp_path: Path,
) -> None:
    """The default path is the board's line, and it differs from the payload's.

    This is the assertion with teeth.  It fails in three directions, and each one
    is a real regression:

    * someone makes ``stage_esp`` fall back to a payload ``unixnu.toml`` it was
      never given -- the two lines converge and this goes red;
    * someone edits the fixture board spec to match the payload -- red, because
      the arm distinction the measurement depends on would no longer exist;
    * someone makes ``kernel_args_line`` drop or rewrite an argument -- red on
      the exact spelling.

    The ``!=`` is the point.  A test that only asserted "the staged line is the
    board's line" would pass just as happily if the two ever became the same,
    which is precisely the state in which the ``--arm`` distinction stops meaning
    anything and a measurement can quietly answer the wrong question.
    """
    inputs = _inputs(tmp_path, None)
    staged = _staged_args(inputs, tmp_path, BOARD_SPEC)
    assert staged == ub.kernel_args_line(BOARD_SPEC), staged

    delivered = "-apfs_shared_datavolume -v serial=3 debug=0x14e " \
                "offline-hid-input=1 offline-hid-home=1 sheng-touch-hid=1"
    row = ub.kernel_args_divergence(staged, delivered)
    assert row["equal"] is False, row
    assert row["only_staged"] == ["offline-legacy-surface-wait-ms=600000"], row
    assert row["only_delivered"] == ["-apfs_shared_datavolume", "debug=0x14e"], row
    assert row["changed"] == [], row
    # Named, not merely counted: the argument that gates the HID consumer has to
    # be the one the report points at.
    assert any("offline-legacy-surface-wait-ms" in item for item in row["only_staged"]), row


def test_the_two_paths_are_two_sources_not_two_spellings(tmp_path: Path) -> None:
    """Same board, same bundle, two different ``args`` lines.

    The failure this pins is the one that cost the most: a run that believes it
    booted the payload's line while ``stage_esp`` generated the board's.  The two
    staged files are compared directly, so the test says nothing about which is
    right -- only that choosing between them is a real choice with a real
    consequence, made by one keyword, recorded nowhere.
    """
    toml = tmp_path / "delivered" / "unixnu.toml"
    with_payload = _staged_args(_inputs(tmp_path / "a", toml), tmp_path / "a", BOARD_SPEC)
    without = _staged_args(_inputs(tmp_path / "b", None), tmp_path / "b", BOARD_SPEC)
    assert with_payload != without, (with_payload, without)
    assert with_payload in PAYLOAD_TOML, with_payload
    assert without == ub.kernel_args_line(BOARD_SPEC), without


def test_a_value_change_is_a_change_not_a_removal_plus_an_addition() -> None:
    """``NAME=1`` against ``NAME=2`` is reported as changed.

    A set-of-names difference would call this one removal and one addition, and a
    caller printing that list would show two arguments when exactly one
    changed -- the shape of report that reads as "I added a flag" when what
    happened is "the guest ignored my flag".  ``debug=0x14e`` against
    ``debug=0x8`` is the concrete case: same name, different value, and the
    difference is the entire finding.
    """
    row = ub.kernel_args_divergence("-v serial=3 debug=0x14e", "-v serial=3 debug=0x8")
    assert row["equal"] is False, row
    assert row["only_staged"] == [], row
    assert row["only_delivered"] == [], row
    assert row["changed"] == ["debug=0x14e -> debug=0x8"], row


def test_identical_lines_are_equal_and_say_so() -> None:
    """The happy path, so a divergence report that always says "differs" is caught.

    Without this, a ``kernel_args_divergence`` that returned ``equal: False``
    unconditionally would satisfy every other test in this file and make the
    payload arm's "ARGS: identical" line meaningless.
    """
    line = "-v serial=3 offline-hid-input=1 offline-hid-home=1 sheng-touch-hid=1"
    row = ub.kernel_args_divergence(line, line)
    assert row == {"equal": True, "only_staged": [], "only_delivered": [], "changed": []}, row


def test_argument_order_is_not_a_divergence() -> None:
    """Reordering the same arguments is not a change.

    The board's list and the payload's list are both hand-maintained and their
    order is not part of the contract -- a diff that treated it as one would fire
    on a cosmetic edit and train everyone to ignore the warning.
    """
    row = ub.kernel_args_divergence("-v serial=3", "serial=3 -v")
    assert row["equal"] is True, row


@pytest.mark.skipif(
    not (REAL_DEVICE / "board.toml").is_file(),
    reason="vendor/UniXNU-qemu is not present in this checkout",
)
def test_the_pinned_board_line_still_diverges_from_the_delivered_payload() -> None:
    """The measured divergence, pinned against the real pinned board.

    This is the only test here that touches the pinned vendor tree, and it is the
    one that would go red if someone reconciled ``board.toml`` with the payload's
    ``unixnu.toml``.  That reconciliation would be a *good* change -- and it would
    retire the ``--arm payload`` versus ``--arm board`` distinction, so the test
    that depends on the distinction has to notice.

    The expected divergence is written out rather than derived, because the whole
    value is that a future edit to ``board.toml`` is reported as a change to a
    recorded fact instead of being absorbed silently.
    """
    spec = ub.read_board_payload(REAL_DEVICE)
    board_line = ub.kernel_args_line(spec)

    row = ub.kernel_args_divergence(board_line, DELIVERED_PAYLOAD_ARGS)
    assert row["equal"] is False, row
    assert "offline-legacy-surface-wait-ms=600000" in row["only_staged"], row
    assert "sheng-fb-gpu=1" in row["only_staged"], row
    assert "sheng-gpu-addon=1" in row["only_staged"], row
    assert row["only_delivered"] == [], row
    assert row["changed"] == [], row
    # 23 delivered arguments against the board's 26: the count is part of the
    # recorded fact, so a fourth argument appearing is visible even if it is one
    # nobody thought to list.
    assert len(DELIVERED_PAYLOAD_ARGS.split()) == 23, DELIVERED_PAYLOAD_ARGS
    assert len(board_line.split()) == 26, board_line
